import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {collectiveClosureDeterministicMaterial} from '../../server/benchmarks/runA2CollectiveClosureEvidence';
import {buildCanonicalA2AssistedStage1Fixture} from '../../engine/planner-next/benchmarks/canonicalA2AssistedStage1Fixture';
import {replayA2AcceptedTasks} from '../../engine/planner-next/benchmarks/a2ClosureSufficiencyDiagnostic';
import {revalidateJointCompletionWitness} from '../../engine/planner-next/jointCompletionWitness';
const hash=(x:any)=>createHash('sha256').update(JSON.stringify(x)).digest('hex');
const runs=[1,2].map(n=>JSON.parse(readFileSync(`work/consolidation/production-run${n}.json`,'utf8')));
assert.deepEqual(collectiveClosureDeterministicMaterial(runs[0]),collectiveClosureDeterministicMaterial(runs[1]));
const source=buildCanonicalA2AssistedStage1Fixture().adapter.problem;
const cam1Tasks=source.tasks.filter(t=>t.requiredResourceIds?.includes('plan-resource:4001'));
assert.equal(cam1Tasks.length,51);
const checks=runs.map((run,runIndex)=>{
 assert.equal(run.status,'PASS');assert.equal(run.stageCount,10);assert.equal(run.completedObligationCount,266);assert.equal(run.finalObligationIdsMatchSource,true);assert.equal(run.duplicateFinalIds,0);assert.equal(run.firstBlocker,null);
 return run.iterations.map((stage:any)=>{
  const witness=stage.futureStructuralWitnesses.find((x:any)=>x.kind==='JOINT_COMPLETION');assert.ok(witness);assert.equal(witness.tasks.length,247);assert.equal(witness.participantMeals.length,19);
  assert.equal(stage.work.coreBranches+stage.work.standaloneBranches,stage.branchesExplored);assert.ok(stage.branchesExplored<=100000);assert.ok(stage.durationMs<=300000);if(stage.ordinal===1)assert.ok(stage.durationMs<=120000);
  assert.equal(stage.protectedEqualityProof.equal,true);assert.equal(stage.newHardViolationCount,0);assert.equal(stage.newRequiredViolationCount,0);assert.equal(stage.sodexoMeals.globalMealGate,'PASS');
  assert.deepEqual(stage.visibleProposalTaskIds,stage.resolvedTaskIds);
  assert.equal(stage.acceptedObligationCountAfter-stage.acceptedObligationCountBefore,stage.newObligationCount);assert.equal(stage.newObligationCount,stage.visibleScopeCount);assert.equal(stage.newTaskPlacementCount+stage.newParticipantMealPlacementCount,stage.newObligationCount);assert.equal(stage.acceptedSnapshotAfter.length,stage.acceptedObligationCountAfter);assert.equal(stage.acceptedSnapshotBefore.length,stage.acceptedObligationCountBefore);
  const expected=source.tasks.filter(t=>stage.resolvedTaskIds.includes(Number(t.id.slice(5)))).map(t=>t.id).sort();
  const visible=stage.newVisibleTasks.map((t:any)=>`task:${t.taskId}`).sort();assert.deepEqual(visible,expected);
  const context=replayA2AcceptedTasks(stage.acceptedSnapshotBefore);let replayCharges=0;
  const replay=revalidateJointCompletionWitness(source,witness,context,()=>{replayCharges++;return stage.branchesExplored+replayCharges<=100000;});
  assert.equal(replay,'PASS');assert.equal(replayCharges,292);
  const cam1=witness.tasks.filter((t:any)=>t.requiredResourceIds?.includes('plan-resource:4001'));assert.equal(cam1.length,51);
  const overlaps=cam1.flatMap((a:any,i:number)=>cam1.slice(i+1).filter((b:any)=>a.start<b.end&&b.start<a.end));assert.equal(overlaps.length,0);
  if(stage.ordinal===1){assert.equal(stage.acceptedSnapshotAfter.length,19);assert.ok(stage.acceptedSnapshotAfter.every((t:any)=>source.tasks.find(x=>x.id===`task:${t.taskId}`)?.kind==='main'));assert.equal(stage.acceptedSupportingPlacements.length,0);}
  return {run:runIndex+1,stage:stage.ordinal,replay,replayCharges,totalIncludingAudit:stage.branchesExplored+replayCharges,jointFingerprint:witness.fingerprint,protectedCount:context.length,taskCount:witness.tasks.length,sodexo:witness.participantMeals.length,cam1Count:cam1.length,cam1Overlaps:overlaps.length,visibleScopeExact:true,ephemeralNotAccepted:true};
 });
});
const result={deterministicEquivalent:true,materialDigest:hash(collectiveClosureDeterministicMaterial(runs[0])),finalFingerprint:runs[0].deterministicFingerprint,checks};
writeFileSync('work/consolidation/verification.json',JSON.stringify(result,null,2));
console.log(JSON.stringify({deterministicEquivalent:true,materialDigest:result.materialDigest,finalFingerprint:result.finalFingerprint,replays:checks.flat().length,replayChargesPerStage:292,cam1Count:51,cam1Overlaps:0}));

