import {writeFileSync} from 'node:fs';
import {runA2Assist7Evidence} from '../../server/benchmarks/runA2Assist7Evidence';
const {AssistedProposalService}=await import('../../server/assistedProposalService');
const original=AssistedProposalService.prototype.run;
const output=process.env.ASST_OBSERVATION_PREFIX??'work/consolidation/asst-current';
const observations:any[]=[];
AssistedProposalService.prototype.run=async function(...args){
 writeFileSync(output+'-active.json',JSON.stringify({active:true,ordinal:observations.length+1,started:Date.now()}));
 const started=performance.now();const result=await original.apply(this,args);
 writeFileSync(output+'-active.json',JSON.stringify({active:false}));
 const observation={ordinal:observations.length+1,durationMs:performance.now()-started,result};observations.push(observation);
 writeFileSync(output+'-observations.json',JSON.stringify(observations));
 console.error(JSON.stringify({ordinal:observation.ordinal,durationMs:observation.durationMs,outcome:result.outcome,reasonCodes:result.reasonCodes,scope:result.scopeTaskIds,branches:result.evidence.work}));
 return result;
};
