import {registerHooks} from 'node:module';
import {writeFileSync} from 'node:fs';
import ts from 'typescript';
const output=process.env.ASST_OBSERVATION_PREFIX??'work/consolidation/asst-current';
let ordinal=0,coreOrdinal=0,halls=0;
globalThis.__asstInput=input=>{ordinal++;coreOrdinal=0;writeFileSync(output+`-input${ordinal}.json`,JSON.stringify(input));};
globalThis.__asstCoreEnter=(candidate,ledger)=>{const frame={request:ordinal,core:++coreOrdinal,source:candidate.source,fingerprint:candidate.fingerprint,started:performance.now()};writeFileSync(output+`-core${ordinal}-${coreOrdinal}.json`,JSON.stringify({candidate,ledger:{limit:ledger.limit,total:ledger.branchesExplored,core:ledger.coreBranches,standalone:ledger.standaloneBranches}}));console.error(JSON.stringify({event:'core_enter',...frame}));return frame;};
globalThis.__asstCoreExit=(frame,evidence,ledger)=>{const keys=['firstParticipantFutureReservationPrune','firstSupportingGeometryRepair','supportingGeometryRepairAttempts','supportingGeometryRepairSuccesses','futureCollectiveClosureInconclusiveLeaves','firstStandaloneDeadEndCause','firstTerminalCompletionRejection','futureCollectiveClosureAbstentions','participantFutureUnreachableDependencyIds','futureCollectiveClosureHall','futureCollectiveClosureChecks','futureCollectiveClosureMatchingTraversals','standaloneSearchInvocations'];const observation=Object.fromEntries(keys.map(key=>[key,evidence[key]]));console.error(JSON.stringify({event:'core_exit',...frame,durationMs:performance.now()-frame.started,branches:ledger.branchesExplored,observation}));};
globalThis.__asstNecessaryResult=(outcome,tasks,check)=>{if(check.status==='INFEASIBLE'&&halls<20){writeFileSync(output+`-hall${++halls}.json`,JSON.stringify({request:ordinal,core:coreOrdinal,tasks,check}));}return outcome;};
const fn=n=>ts.isFunctionDeclaration(n)||ts.isFunctionExpression(n)||ts.isArrowFunction(n)||ts.isMethodDeclaration(n);
const name=n=>n.name?.getText()??(ts.isCallExpression(n.parent)&&n.parent.expression.getText()==='__name'?n.parent.arguments[1]?.text:ts.isVariableDeclaration(n.parent)?n.parent.name.getText():null);
registerHooks({load(url,context,next){const result=next(url,context);if(!url.endsWith('/assistedPlanning.ts')&&!url.endsWith('/exactItinerantPlan.ts'))return result;
 let source=typeof result.source==='string'?result.source:Buffer.from(result.source).toString();
 const tree=ts.createSourceFile('observer.js',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.JS),edits=[];
 const visit=n=>{if(fn(n)&&n.body&&ts.isBlock(n.body)){
  const key=name(n);
  if(key==='necessary'){const returns=t=>{if(fn(t)&&t!==n)return;if(ts.isReturnStatement(t)&&t.expression)edits.push({pos:t.expression.getStart(),end:t.expression.end,text:` globalThis.__asstNecessaryResult((${t.expression.getText()}),tasks,check)`});ts.forEachChild(t,returns);};returns(n);}
  if(key==='executeAssistedPlanning')edits.push({pos:n.body.getStart()+1,text:'globalThis.__asstInput(input);'});
  if(key==='onHardValidCoreLeaf'){
   edits.push({pos:n.body.getStart()+1,text:'const __asstFrame=globalThis.__asstCoreEnter(candidate,ledger);try {'});
   edits.push({pos:n.body.end-1,text:'} finally {globalThis.__asstCoreExit(__asstFrame,evidence,ledger);}'});
  }
 }ts.forEachChild(n,visit);};visit(tree);
 for(const edit of edits.sort((a,b)=>b.pos-a.pos))source=source.slice(0,edit.pos)+edit.text+source.slice(edit.end??edit.pos);
 return {...result,source};}});

