import {readFileSync,writeFileSync} from 'node:fs';
import {exactTaskStartDomain} from '../../engine/planner-next/placement';
import {PreparedFutureCollectiveParticipantClosure} from '../../engine/planner-next/futureCollectiveParticipantClosure';
import {assessCoreArrivalTransportFeasibility} from '../../engine/planner-next/transportGrouping';
import {createExactSearchLedger} from '../../engine/planner-next/exactMainAndFeederCore';
import type {AssistedProblem} from '../../engine/planner-next/assistedPlanning';
import type {ScheduledTask} from '../../engine/planner-next/contracts';
const prefix=process.argv[2]??'work/consolidation/asst-partial-gate-valid';
const first=JSON.parse(readFileSync(prefix+'-input1.json','utf8')) as AssistedProblem;
const current=JSON.parse(readFileSync(prefix+'-input2.json','utf8')) as AssistedProblem;
const observed=JSON.parse(readFileSync(prefix+'-core2-1.json','utf8'));
const problem={...current.collectiveCoreProjection!.problem,budget:{...current.problem.budget,maxBranchExpansions:observed.ledger.limit}};
const candidate=observed.candidate as {tasks:ScheduledTask[];meals:any[]};
const joint=problem.analyticalFutureCollectiveContinuation!;
const protectedIds=new Set(current.protectedPlacements.map(task=>task.id));
const arrivals=new Set(problem.transportPolicy?.arrival.taskIds);
const entries=new Set(problem.tasks.filter(task=>task.kind==='auxiliary'&&task.dependencies.some(id=>arrivals.has(id))
 &&problem.tasks.some(main=>main.kind==='main'&&main.participantId===task.participantId&&main.dependencies.includes(task.id))).map(task=>task.id));
const repairIds=new Set(candidate.tasks.filter(task=>!protectedIds.has(task.id)&&(arrivals.has(task.id)||entries.has(task.id))).map(task=>task.id));
const nominal=new PreparedFutureCollectiveParticipantClosure(joint);
const ledger=createExactSearchLedger(observed.ledger.limit);
const before=nominal.evaluate(candidate.tasks,[],()=>ledger.consume('STANDALONE'),'NECESSARY_ONLY',candidate.meals);
const blocker=joint.tasks.find(task=>task.id===before.hall?.closureTaskIds[0]);
const retained=candidate.tasks.filter(task=>!repairIds.has(task.id));
const arrival=assessCoreArrivalTransportFeasibility(problem,retained,{consumeFallbackBranch:()=>ledger.consume('STANDALONE')});
const rebuilt=[...new Map([...arrival.scheduled??[],...retained].map(task=>[task.id,task])).values()];
const after=nominal.evaluate(rebuilt,[],()=>ledger.consume('STANDALONE'),'NECESSARY_ONLY',candidate.meals);
const oldById=new Map(first.collectiveCoreProjection!.problem.tasks.map(task=>[task.id,task]));
const changed=problem.tasks.filter(task=>oldById.get(task.id)&&oldById.get(task.id)!.duration!==task.duration)
 .map(task=>({id:task.id,before:oldById.get(task.id)!.duration,after:task.duration}));
const result={qualification:'Read-only diagnosis of the first actual S2 core. Captured request inputs are observations, never seeds for A2 or evidence of a completed S2. Positive necessary capacity is not certification.',
 scope:current.scope,protectedPlacements:current.protectedPlacements,changedDurations:changed,effectiveBudget:ledger.limit,
 firstCoreFingerprint:observed.candidate.fingerprint,nominalClosure:before,arrivalResult:arrival.status,
 blocker: blocker?{id:blocker.id,participantId:blocker.participantId,spaceId:blocker.spaceId,requiredResourceIds:blocker.requiredResourceIds,
  nominalDomain:exactTaskStartDomain(problem,blocker,candidate.tasks,candidate.meals).intervals,
  repairedDomain:exactTaskStartDomain(problem,blocker,rebuilt,candidate.meals).intervals}:null,
 repairedNecessaryClosure:after,deferredSupportingIds:[...repairIds].sort(),
 diagnosticCharges:ledger.branchesExplored,protectedPreserved:current.protectedPlacements.every(fixed=>{
 const actual=rebuilt.find(task=>task.id===fixed.id);return actual&&JSON.stringify(actual)===JSON.stringify(fixed);}),
 globalS2Certificate:false,globalInfeasibilityProved:false};
writeFileSync('work/consolidation/asst-first-authority.json',JSON.stringify(result,null,2));
console.log(JSON.stringify({nominal:before.status,hall:before.hall,repairedNecessary:after.status,arrival:arrival.status,diagnosticCharges:ledger.branchesExplored,protectedPreserved:result.protectedPreserved,changed:changed.length}));
